        private static bool IsImageUrl(string url, ref Result result)
        {
            try
            {
                var req = (HttpWebRequest)HttpWebRequest.Create(url);
                req.Timeout = 5000; ////set the timeout to 5 seconds to keep the user from waiting too long for the page to load
                req.Method = "HEAD";
                int contentLength = 0;
                using (var resp = req.GetResponse())
                {
                    int.TryParse(resp.Headers.Get("Content-Length"), out contentLength);

                     bool isValidFile = IsValidFileSize(contentLength);
                     if (!isValidFile)
